insert into questoes (id,materia,topico,tipo,enunciado,alternativas,aluno) values
  ('juju-ing-t01','ingles','Things in nature (SB 92-93 / WB 77)','treino','Como se diz "montanha" em inglês?','["river", "mountain", "road", "cloud"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t02','ingles','Things in nature (SB 92-93 / WB 77)','treino','O que é "river"?','["Rio", "Estrela", "Caverna", "Campo"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t03','ingles','Things in nature (SB 92-93 / WB 77)','treino','Qual palavra significa "nuvem"?','["star", "bat", "cloud", "cave"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t04','ingles','Things in nature (SB 92-93 / WB 77)','treino','Um animal que voa à noite e gosta de cavernas, em inglês, é:','["bat", "field", "road", "star"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t05','ingles','Things in nature (SB 92-93 / WB 77)','treino','O que significa "cave"?','["Estrada", "Nuvem", "Rio", "Caverna"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t06','ingles','Things in nature (SB 92-93 / WB 77)','treino','Complete: "At night, I can see a ______ in the sky." (uma estrela no céu)','["road", "star", "river", "field"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t07','ingles','Things in nature (SB 92-93 / WB 77)','treino','Os carros andam na:','["field", "cave", "road", "cloud"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t08','ingles','Grammar: was/wasn''t, were/weren''t (SB 93 / WB 78)','treino','Complete: "There ______ a river." (Havia um rio.)','["were", "was", "weren''t", "are"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t09','ingles','Grammar: was/wasn''t, were/weren''t (SB 93 / WB 78)','treino','Complete: "There ______ some bats." (Havia alguns morcegos.)','["was", "wasn''t", "is", "were"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t10','ingles','Grammar: was/wasn''t, were/weren''t (SB 93 / WB 78)','treino','"There wasn''t a road." quer dizer:','["Havia uma estrada.", "Não havia uma estrada.", "Há muitas estradas.", "A estrada é grande."]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t11','ingles','Grammar: was/wasn''t, were/weren''t (SB 93 / WB 78)','treino','Complete: "There ______ any clouds." (Não havia nuvens.)','["weren''t", "wasn''t", "was", "were"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t12','ingles','Grammar: was/wasn''t, were/weren''t (SB 93 / WB 78)','treino','Complete a pergunta: "______ there a cave?"','["Were", "Is", "Was", "Are"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t13','ingles','Grammar: was/wasn''t, were/weren''t (SB 93 / WB 78)','treino','"Were there any stars?" Qual resposta está certa para "sim"?','["Yes, there was.", "Yes, there were.", "Yes, there wasn''t.", "Yes, there is."]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t14','ingles','Grammar: was/wasn''t, were/weren''t (SB 93 / WB 78)','treino','"Was there a field?" Qual resposta está certa para "não"?','["No, there weren''t.", "No, there were.", "No, there isn''t.", "No, there wasn''t."]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t15','ingles','Prepositions: directions (SB 96 / WB 80)','treino','O menino sobe a escada. Em inglês, ele vai:','["down", "up", "out", "along"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t16','ingles','Prepositions: directions (SB 96 / WB 80)','treino','O que significa "down"?','["Para baixo", "Para dentro", "Em volta", "Para cima"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t17','ingles','Prepositions: directions (SB 96 / WB 80)','treino','A família entra na barraca. Qual palavra mostra "para dentro"?','["out", "across", "into", "up"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t18','ingles','Prepositions: directions (SB 96 / WB 80)','treino','O gato sai da caixa. Ele vai:','["into the box", "up the box", "along the box", "out of the box"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t19','ingles','Prepositions: directions (SB 96 / WB 80)','treino','As crianças correm em volta da árvore. "Em volta" em inglês é:','["around", "across", "down", "into"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t20','ingles','Prepositions: directions (SB 96 / WB 80)','treino','Atravessar a rua de um lado para o outro é ir ______ the road.','["along", "across", "up", "out"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t21','ingles','Prepositions: directions (SB 96 / WB 80)','treino','Caminhar pela beira do rio, seguindo o caminho dele, é ir ______ the river.','["into", "down", "along", "out"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t22','ingles','Grammar: went and didn''t go (SB 97 / WB 81)','treino','Qual é o passado de "go" (ir)?','["goed", "going", "goes", "went"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t23','ingles','Grammar: went and didn''t go (SB 97 / WB 81)','treino','"We went to the beach." quer dizer:','["Nós fomos à praia.", "Nós vamos à praia.", "Nós não fomos à praia.", "Nós gostamos da praia."]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t24','ingles','Grammar: went and didn''t go (SB 97 / WB 81)','treino','"I didn''t go to the park." quer dizer:','["Eu fui ao parque.", "Eu não fui ao parque.", "Eu vou ao parque.", "Eu gosto do parque."]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t25','ingles','Grammar: went and didn''t go (SB 97 / WB 81)','treino','Complete: "Where ______ you go yesterday?"','["was", "were", "did", "went"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t26','ingles','Grammar: went and didn''t go (SB 97 / WB 81)','treino','Complete: "Yesterday, we ______ to the zoo." (Ontem nós fomos ao zoológico.)','["go", "went", "goes", "didn''t"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t27','ingles','Grammar: went and didn''t go (SB 97 / WB 81)','treino','Qual frase está certa?','["We didn''t went to school.", "We didn''t goes to school.", "We not go to school.", "We didn''t go to school."]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-t28','ingles','Grammar: went and didn''t go (SB 97 / WB 81)','treino','"Didn''t" é a forma curta de:','["did not", "do not", "is not", "was not"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-p01','ingles','Things in nature (SB 92-93 / WB 77)','prova','Qual grupo tem só coisas da natureza?','["mountain, river, cloud", "car, bus, road", "pen, book, bag", "TV, phone, radio"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-p02','ingles','Things in nature (SB 92-93 / WB 77)','prova','"There are many cows in the ______." (Há muitas vacas no campo.)','["sky", "cave", "field", "cloud"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-p03','ingles','Things in nature (SB 92-93 / WB 77)','prova','Que palavra NÃO combina com o céu (sky)?','["star", "cloud", "bat", "river"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-p04','ingles','Grammar: was/wasn''t, were/weren''t (SB 93 / WB 78)','prova','Escolha a frase certa: "Havia algumas estrelas."','["There was some stars.", "There were some stars.", "There weren''t a star.", "There is some stars."]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-p05','ingles','Grammar: was/wasn''t, were/weren''t (SB 93 / WB 78)','prova','Leia: "Last night there was a moon, but there weren''t any clouds." O que havia no céu?','["Nuvens, mas não a lua", "Nada", "A lua, mas nenhuma nuvem", "Lua e muitas nuvens"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-p06','ingles','Grammar: was/wasn''t, were/weren''t (SB 93 / WB 78)','prova','"Was there a bat in the cave?" "Yes, there ______."','["was", "were", "wasn''t", "weren''t"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-p07','ingles','Prepositions: directions (SB 96 / WB 80)','prova','Para entrar na caverna e depois sair dela, usamos:','["up e down", "into e out of", "around e along", "across e up"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-p08','ingles','Prepositions: directions (SB 96 / WB 80)','prova','"The children walked ______ the mountain to the top." (subiram até o topo)','["down", "out of", "up", "into"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-p09','ingles','Prepositions: directions (SB 96 / WB 80)','prova','Qual palavra significa "atravessando, de um lado para o outro"?','["along", "around", "down", "across"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-p10','ingles','Grammar: went and didn''t go (SB 97 / WB 81)','prova','"Did you go to the river?" "No, we ______ to the river."','["didn''t go", "didn''t went", "went not", "don''t went"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-p11','ingles','Grammar: went and didn''t go (SB 97 / WB 81)','prova','Leia: "Ana went into the cave. She didn''t go up the mountain." Para onde Ana foi?','["Subiu a montanha", "Para dentro da caverna", "Atravessou o rio", "Não foi a lugar nenhum"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-ing-p12','ingles','Grammar: went and didn''t go (SB 97 / WB 81)','prova','Qual frase está no passado?','["We go to the field.", "We are going to the field.", "We went to the field.", "We like the field."]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd');
insert into gabarito (questao_id,correta,explicacao) values
  ('juju-ing-t01',1,'Mountain = montanha. River = rio, road = estrada, cloud = nuvem.'),
  ('juju-ing-t02',0,'River = rio. Um rio tem água que corre.'),
  ('juju-ing-t03',2,'Cloud = nuvem. Ela fica no céu.'),
  ('juju-ing-t04',0,'Bat = morcego. Ele dorme em cavernas (caves) e voa à noite.'),
  ('juju-ing-t05',3,'Cave = caverna, um buraco grande dentro da montanha ou da pedra.'),
  ('juju-ing-t06',1,'Star = estrela. À noite vemos estrelas no céu.'),
  ('juju-ing-t07',2,'Road = estrada. É por onde passam os carros.'),
  ('juju-ing-t08',1,'Usamos "was" para uma coisa só, no passado: There was a river.'),
  ('juju-ing-t09',3,'Para mais de uma coisa (bats) usamos "were": There were some bats.'),
  ('juju-ing-t10',1,'Wasn''t = was not = não havia (para uma coisa só).'),
  ('juju-ing-t11',0,'Clouds são várias, então usamos "were". Na negativa: weren''t.'),
  ('juju-ing-t12',2,'Cave é uma coisa só, então a pergunta no passado é "Was there a cave?".'),
  ('juju-ing-t13',1,'A pergunta usa "were" (stars são várias), então a resposta é "Yes, there were."'),
  ('juju-ing-t14',3,'A pergunta usa "was", então a resposta negativa é "No, there wasn''t."'),
  ('juju-ing-t15',1,'Up = para cima. Down = para baixo.'),
  ('juju-ing-t16',0,'Down = para baixo, como descer uma montanha.'),
  ('juju-ing-t17',2,'Into = para dentro. Out = para fora.'),
  ('juju-ing-t18',3,'Out of = para fora de. O gato sai da caixa: out of the box.'),
  ('juju-ing-t19',0,'Around = em volta, ao redor.'),
  ('juju-ing-t20',1,'Across = atravessando, de um lado para o outro.'),
  ('juju-ing-t21',2,'Along = ao longo de, seguindo o caminho.'),
  ('juju-ing-t22',3,'"Go" é um verbo diferente: no passado vira "went", e não "goed".'),
  ('juju-ing-t23',0,'Went = fomos/foi (passado de go).'),
  ('juju-ing-t24',1,'Didn''t go = não fui. Didn''t = did not.'),
  ('juju-ing-t25',2,'Para perguntar no passado usamos "did": Where did you go?'),
  ('juju-ing-t26',1,'"Yesterday" mostra passado, então usamos "went".'),
  ('juju-ing-t27',3,'Depois de "didn''t" o verbo volta ao normal: didn''t GO, e não "didn''t went".'),
  ('juju-ing-t28',0,'Didn''t = did not (não, no passado).'),
  ('juju-ing-p01',0,'Mountain (montanha), river (rio) e cloud (nuvem) são coisas da natureza.'),
  ('juju-ing-p02',2,'Field = campo. É onde as vacas ficam pastando.'),
  ('juju-ing-p03',3,'Estrelas, nuvens e morcegos podem aparecer no céu. River (rio) fica no chão.'),
  ('juju-ing-p04',1,'Stars são várias, então usamos "were": There were some stars.'),
  ('juju-ing-p05',2,'There was a moon = havia uma lua. There weren''t any clouds = não havia nuvens.'),
  ('juju-ing-p06',0,'A pergunta usa "was" e a resposta é "sim": Yes, there was.'),
  ('juju-ing-p07',1,'Into = para dentro; out of = para fora de.'),
  ('juju-ing-p08',2,'Para chegar ao topo, eles subiram: up the mountain.'),
  ('juju-ing-p09',3,'Across = atravessando. Along = seguindo o caminho; around = em volta.'),
  ('juju-ing-p10',0,'Na negativa do passado: didn''t + go. Fica "we didn''t go".'),
  ('juju-ing-p11',1,'Ana went into the cave = Ana foi para dentro da caverna. Ela não subiu a montanha.'),
  ('juju-ing-p12',2,'"Went" é o passado de "go". As outras frases não estão no passado.');
